import {expect, test} from '@mattermost/playwright-lib';

import {closeGuardedSessions, openGuardedSession} from '../src/session';

test.afterEach(closeGuardedSessions);

/**
 * @objective Archived public channel: Info panel shows the archived notice and is read-only for a regular member (MX-21).
 * Seed-bound text checks use expect.soft so a negative-control seed reports every failing declared string
 * while navigation and visibility stay hard assertions.
 */
test(
    'PILOT-02 archived public channel: Info panel shows the archived notice and is read-only for a regular member',
    {tag: ['@channels', '@channel_info', '@explorer_pilot']},
    async ({pw}) => {
        const {page, channelsPage} = await openGuardedSession(pw);
        const info = page.getByRole('region', {name: 'Info', exact: true});

        // # Go to /qa-team/channels/legacy-roadmap (exploration root, state s3f16dcc6)
        await channelsPage.goto('qa-team', 'legacy-roadmap');
        await channelsPage.centerView.header.toBeVisible();

        // # Click button "View Info" (discovered: trace #1, region "Info" appeared)
        await page.getByRole('button', {name: 'View Info', exact: true}).click();
        await expect(info).toBeVisible(); // smoke: observed transition #1 (region "Info" appeared)

        // * Checkpoint assertions: declared (scenarios.json PILOT-02 expected_outcome.assertions)
        await expect(info).toBeVisible(); // declared (scenarios.json PILOT-02)
        await expect(info.getByText('This channel is archived.', {exact: true})).toBeVisible(); // declared (scenarios.json PILOT-02)
        // Unarchive: absence is asserted for a regular member (needs manage_team). Presence of this exact name is exercised by the verify control with the same user as team admin, not by this spec.
        await expect(info.getByRole('button', {name: 'Unarchive', exact: true})).toHaveCount(0); // declared (scenarios.json PILOT-02)
        // Substring name on purpose: the live name carries an icon glyph prefix, so an exact name could not detect presence.
        await expect(info.getByRole('button', {name: /Add People/})).toHaveCount(0); // declared (scenarios.json PILOT-02)
        await expect(info.getByRole('button', {name: 'Edit', exact: true})).toHaveCount(0); // declared (scenarios.json PILOT-02)
        await expect(info.getByRole('button', {name: 'Notification Preferences', exact: true})).toHaveCount(0); // declared (scenarios.json PILOT-02)
        await expect(info.getByRole('button', {name: 'Channel Settings', exact: true})).toHaveCount(0); // declared (scenarios.json PILOT-02)
        await expect.soft(info).toContainText('Legacy purpose charlie-4e8a'); // declared (scenarios.json PILOT-02)
        await expect.soft(info).toContainText('Legacy header charlie-4e8a'); // declared (scenarios.json PILOT-02)
        await expect(info.getByRole('button', {name: 'Members', exact: true})).toBeVisible(); // declared (scenarios.json PILOT-02)
        await expect(info.getByRole('button', {name: 'Copy Link', exact: true})).toBeVisible(); // declared (scenarios.json PILOT-02)
    },
);
